cd /workspace && node -e "
const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Extract text from .docx ---
const buf = fs.readFileSync('testbed/docs/customer_report.docx');
let xmlContent = '';
let offset = 0;
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) !== 0x04034b50) break;
  const compressionMethod = buf.readUInt16LE(offset + 8);
  const compressedSize = buf.readUInt32LE(offset + 18);
  const fileNameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fileName = buf.toString('utf8', offset + 30, offset + 30 + fileNameLen);
  const dataStart = offset + 30 + fileNameLen + extraLen;
  if (fileName === 'word/document.xml') {
    let data;
    if (compressionMethod === 0) {
      data = buf.slice(dataStart, dataStart + compressedSize);
    } else {
      data = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compressedSize));
    }
    xmlContent = data.toString('utf8');
    break;
  }
  offset = dataStart + compressedSize;
}

// --- Parse paragraphs ---
const paragraphs = xmlContent.split(/<w:p[ >]/).slice(1);
const lines = [];
for (const para of paragraphs) {
  const tMatches = [...para.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
  const line = tMatches.map(m => m[1]).join('');
  // Detect bold
  const isBold = para.includes('<w:b/>') || para.includes('<w:b ');
  // Detect font size (w:sz val is in half-points)
  const szMatch = para.match(/<w:sz w:val=\"(\d+)\"/);
  const fontSize = szMatch ? parseInt(szMatch[1]) / 2 : 11;
  lines.push({ text: line, bold: isBold, fontSize });
}

// --- Generate PDF ---
const doc = new PDFDocument({ margin: 50 });
const outPath = 'testbed/docs/customer_report.pdf';
const stream = fs.createWriteStream(outPath);
doc.pipe(stream);

for (const line of lines) {
  const size = line.fontSize > 20 ? 18 : (line.fontSize > 13 ? 14 : 11);
  const font = line.bold ? 'Helvetica-Bold' : 'Helvetica';
  doc.font(font).fontSize(size);
  doc.text(line.text, { paragraphGap: line.text === '' ? 4 : 2 });
}

doc.end();
stream.on('finish', () => {
  const stats = fs.statSync(outPath);
  console.log('PDF created: ' + outPath + ' (' + (stats.size / 1024).toFixed(1) + ' KB)');
});
